class O{char[][]G;int r,c,d,u,v;String s(boolean p,String s){if(!p)s=s.replace("#","##").replace("O","[]").replace(".","..").replace("@","@.");var x=s.split("\n\n");var a=x[0].split("\n");G=new char[a.length][];for(int i=0;i<a.length;i++){G[i]=a[i].toCharArray();for(int j=0;j<G[i].length;j++)if(G[i][j]==64){r=i;c=j;G[i][j]=46;}}for(var z:x[1].replace("\n","").toCharArray()){d="^v<>".indexOf(z);u=d<2?d*2-1:0;v=d>1?d*2-5:0;if(f(r+u,c+v,0))f(r+=u,c+=v,1);}long n=0;for(int i=0;i<G.length;i++)for(int j=0;j<G[i].length;j++)if(G[i][j]%12==7)n+=i*100L+j;return n+"";}boolean f(int i,int j,int m){var x=G[i][j];if(x<36)return 1<0;if(x<47)return 1>0;int a=i+u,b=j+v;if(x<91|d>1){if(!f(a,b,m))return 1<0;if(m>0){G[a][b]=x;G[i][j]=46;}return 1>0;}if(x>91)j--;if(!f(i+u,j,m)||!f(i+u,j+1,m))return 1<0;if(m>0){G[i+u][j]=91;G[i+u][j+1]=93;G[i][j]=G[i][j+1]=46;}return 1>0;}}
